UPDATE public.site_content SET content = jsonb_set(content, '{quotes}', '[{"quote": {"ar": "نحن نشكّل مبانينا، ثم تعود مبانينا لتشكّلنا.", "en": "We shape our buildings; thereafter they shape us."}, "author": {"ar": "ونستون تشرشل", "en": "Winston Churchill"}}, {"quote": {"ar": "الأقل هو الأكثر.", "en": "Less is more."}, "author": {"ar": "ميس فان دير روه", "en": "Ludwig Mies van der Rohe"}}, {"quote": {"ar": "الله في التفاصيل.", "en": "God is in the details."}, "author": {"ar": "يُنسب إلى ميس فان دير روه", "en": "Attributed to Ludwig Mies van der Rohe"}}, {"quote": {"ar": "تبدأ العمارة حين تضع طوبتين معًا بعناية. هناك تبدأ.", "en": "Architecture starts when you carefully put two bricks together. There it begins."}, "author": {"ar": "ميس فان دير روه", "en": "Ludwig Mies van der Rohe"}}, {"quote": {"ar": "العمارة هي إرادة العصر مترجمةً إلى فراغ.", "en": "Architecture is the will of an epoch translated into space."}, "author": {"ar": "ميس فان دير روه", "en": "Ludwig Mies van der Rohe"}}, {"quote": {"ar": "الشكل يتبع الوظيفة.", "en": "Form follows function."}, "author": {"ar": "لويس سوليفان", "en": "Louis Sullivan"}}, {"quote": {"ar": "البيت آلة للسكن.", "en": "A house is a machine for living in."}, "author": {"ar": "لو كوربوزييه", "en": "Le Corbusier"}}, {"quote": {"ar": "المكان والضوء والنظام؛ هذه أشياء يحتاجها الإنسان بقدر حاجته إلى الخبز ومكان للنوم.", "en": "Space and light and order. Those are the things that men need just as much as they need bread or a place to sleep."}, "author": {"ar": "لو كوربوزييه", "en": "Le Corbusier"}}, {"quote": {"ar": "العمارة هي اللعب المتقن الصحيح البديع بالكتل المجتمعة تحت الضوء.", "en": "Architecture is the masterly, correct and magnificent play of masses brought together in light."}, "author": {"ar": "لو كوربوزييه", "en": "Le Corbusier"}}, {"quote": {"ar": "العمارة هي الصناعة المتأنية للفراغ.", "en": "Architecture is the thoughtful making of space."}, "author": {"ar": "لويس كان", "en": "Louis Kahn"}}, {"quote": {"ar": "لم تكن الشمس تعرف مدى عظمتها حتى سقطت على جدار مبنى.", "en": "The sun never knew how great it was until it hit the side of a building."}, "author": {"ar": "لويس كان", "en": "Louis Kahn"}}, {"quote": {"ar": "حتى الطوبة تريد أن تكون شيئًا.", "en": "Even a brick wants to be something."}, "author": {"ar": "لويس كان", "en": "Louis Kahn"}}, {"quote": {"ar": "ادرس الطبيعة، أحبّ الطبيعة، ابقَ قريبًا منها؛ فلن تخذلك أبدًا.", "en": "Study nature, love nature, stay close to nature. It will never fail you."}, "author": {"ar": "فرانك لويد رايت", "en": "Frank Lloyd Wright"}}, {"quote": {"ar": "الطبيب يستطيع أن يدفن أخطاءه، أما المعماري فلا يملك إلا أن ينصح عملاءه بزراعة اللبلاب.", "en": "A doctor can bury his mistakes but an architect can only advise his clients to plant vines."}, "author": {"ar": "فرانك لويد رايت", "en": "Frank Lloyd Wright"}}, {"quote": {"ar": "ينبغي أن تتحدث العمارة عن زمانها ومكانها، وأن تتوق إلى الخلود.", "en": "Architecture should speak of its time and place, but yearn for timelessness."}, "author": {"ar": "فرانك جيري", "en": "Frank Gehry"}}, {"quote": {"ar": "هناك 360 درجة، فلماذا نلتزم بواحدة؟", "en": "There are 360 degrees, so why stick to one?"}, "author": {"ar": "زها حديد", "en": "Zaha Hadid"}}, {"quote": {"ar": "العمارة في جوهرها تتعلق بالرفاهية؛ الناس يريدون أن يشعروا بالراحة في المكان.", "en": "Architecture is really about well-being. I think that people want to feel good in a space."}, "author": {"ar": "زها حديد", "en": "Zaha Hadid"}}, {"quote": {"ar": "العمارة فن بصري، والمباني تتحدث عن نفسها.", "en": "Architecture is a visual art, and the buildings speak for themselves."}, "author": {"ar": "جوليا مورغان", "en": "Julia Morgan"}}, {"quote": {"ar": "كل موقف جديد يتطلب عمارة جديدة.", "en": "Each new situation requires a new architecture."}, "author": {"ar": "جان نوفيل", "en": "Jean Nouvel"}}, {"quote": {"ar": "كل العمارة مأوى، والعمارة العظيمة هي تصميم فراغ يحتضن من فيه أو يرفعه أو يحفّزه.", "en": "All architecture is shelter, all great architecture is the design of space that contains, cuddles, exalts, or stimulates the persons in that space."}, "author": {"ar": "فيليب جونسون", "en": "Philip Johnson"}}, {"quote": {"ar": "حين نبني، فلنفكّر أننا نبني للأبد.", "en": "When we build, let us think that we build forever."}, "author": {"ar": "جون راسكن", "en": "John Ruskin"}}, {"quote": {"ar": "الجودة ليست مصادفة أبدًا؛ إنها دائمًا نتيجة جهد ذكي.", "en": "Quality is never an accident; it is always the result of intelligent effort."}, "author": {"ar": "جون راسكن", "en": "John Ruskin"}}, {"quote": {"ar": "للبناء الجيد ثلاثة شروط: المتانة، والمنفعة، والبهجة.", "en": "Well building hath three conditions: firmness, commodity, and delight."}, "author": {"ar": "هنري ووتون", "en": "Henry Wotton"}}, {"quote": {"ar": "الضوء أكبر بنات الخالق، وهو من أبرز جماليات المبنى.", "en": "Light, God''s eldest daughter, is a principal beauty in a building."}, "author": {"ar": "توماس فولر", "en": "Thomas Fuller"}}, {"quote": {"ar": "العمارة موسيقى متجمدة.", "en": "Architecture is frozen music."}, "author": {"ar": "يُنسب إلى غوته", "en": "Attributed to Johann Wolfgang von Goethe"}}, {"quote": {"ar": "المباني الجيدة تأتي من أناس جيدين، وكل المشكلات يحلّها التصميم الجيد.", "en": "Good buildings come from good people, and all problems are solved by good design."}, "author": {"ar": "ستيفن غاردنر", "en": "Stephen Gardiner"}}, {"quote": {"ar": "التصميم الجيد هو أقل قدر ممكن من التصميم.", "en": "Good design is as little design as possible."}, "author": {"ar": "ديتر رامز", "en": "Dieter Rams"}}, {"quote": {"ar": "التفاصيل ليست مجرد تفاصيل؛ إنها التي تصنع التصميم.", "en": "The details are not the details. They make the design."}, "author": {"ar": "تشارلز إيمز", "en": "Charles Eames"}}, {"quote": {"ar": "إدراك الحاجة هو الشرط الأول للتصميم.", "en": "Recognizing the need is the primary condition for design."}, "author": {"ar": "تشارلز إيمز", "en": "Charles Eames"}}, {"quote": {"ar": "لا تضع في بيتك شيئًا لا تعرف أنه نافع أو لا تؤمن بأنه جميل.", "en": "Have nothing in your houses that you do not know to be useful, or believe to be beautiful."}, "author": {"ar": "ويليام موريس", "en": "William Morris"}}, {"quote": {"ar": "التصميم ليس كيف يبدو الشيء فقط؛ التصميم هو كيف يعمل.", "en": "Design is not just what it looks like and feels like. Design is how it works."}, "author": {"ar": "ستيف جوبز", "en": "Steve Jobs"}}, {"quote": {"ar": "الأساليب تأتي وتذهب؛ أما التصميم الجيد فلغة وليس أسلوبًا.", "en": "Styles come and go. Good design is a language, not a style."}, "author": {"ar": "ماسيمو فينيلّي", "en": "Massimo Vignelli"}}, {"quote": {"ar": "البساطة هي قمة التطور.", "en": "Simplicity is the ultimate sophistication."}, "author": {"ar": "يُنسب إلى ليوناردو دافنشي", "en": "Attributed to Leonardo da Vinci"}}, {"quote": {"ar": "الناس يتجاهلون التصميم الذي يتجاهلهم.", "en": "People ignore design that ignores people."}, "author": {"ar": "فرانك شيميرو", "en": "Frank Chimero"}}, {"quote": {"ar": "التصميم الجيد تجارة جيدة.", "en": "Good design is good business."}, "author": {"ar": "توماس واتسون الابن", "en": "Thomas J. Watson Jr."}}, {"quote": {"ar": "التصميم هو التفكير وقد صار مرئيًا.", "en": "Design is thinking made visual."}, "author": {"ar": "سول باس", "en": "Saul Bass"}}, {"quote": {"ar": "أفضل الغرف هي التي تقول شيئًا عن الناس الذين يعيشون فيها.", "en": "The best rooms have something to say about the people who live in them."}, "author": {"ar": "ديفيد هيكس", "en": "David Hicks"}}, {"quote": {"ar": "جوهر التصميم الداخلي سيظل دائمًا الناس وطريقة عيشهم.", "en": "The essence of interior design will always be about people and how they live."}, "author": {"ar": "ألبرت هادلي", "en": "Albert Hadley"}}, {"quote": {"ar": "ينبغي أن يحكي بيتك قصة من أنت، وأن يكون مجموعة مما تحب.", "en": "Your home should tell the story of who you are, and be a collection of what you love."}, "author": {"ar": "نيت بيركوس", "en": "Nate Berkus"}}, {"quote": {"ar": "الأناقة هي الرفض.", "en": "Elegance is refusal."}, "author": {"ar": "كوكو شانيل", "en": "Coco Chanel"}}, {"quote": {"ar": "الموضة تبهت، ويبقى الأسلوب وحده.", "en": "Fashion fades, only style remains the same."}, "author": {"ar": "كوكو شانيل", "en": "Coco Chanel"}}, {"quote": {"ar": "اللون قوة تؤثر في الروح مباشرة.", "en": "Color is a power which directly influences the soul."}, "author": {"ar": "فاسيلي كاندينسكي", "en": "Wassily Kandinsky"}}, {"quote": {"ar": "اللون هو هوسي طوال اليوم، وبهجتي وعذابي.", "en": "Colour is my day-long obsession, joy and torment."}, "author": {"ar": "كلود مونيه", "en": "Claude Monet"}}, {"quote": {"ar": "لا مكان مثل البيت، مهما كان متواضعًا.", "en": "Be it ever so humble, there''s no place like home."}, "author": {"ar": "جون هوارد باين", "en": "John Howard Payne"}}, {"quote": {"ar": "الحنين إلى البيت يسكن فينا جميعًا.", "en": "The ache for home lives in all of us."}, "author": {"ar": "مايا أنجيلو", "en": "Maya Angelou"}}, {"quote": {"ar": "«البيت» أجمل كلمة على الإطلاق.", "en": "Home is the nicest word there is."}, "author": {"ar": "لورا إنغالز وايلدر", "en": "Laura Ingalls Wilder"}}, {"quote": {"ar": "حيث نحب يكون البيت؛ بيت قد تغادره أقدامنا، لكن لا تغادره قلوبنا.", "en": "Where we love is home — home that our feet may leave, but not our hearts."}, "author": {"ar": "أوليفر ويندل هولمز", "en": "Oliver Wendell Holmes Sr."}}, {"quote": {"ar": "بيتك هو جسدك الأكبر؛ ينمو في الشمس وينام في سكون الليل.", "en": "Your house is your larger body. It grows in the sun and sleeps in the stillness of the night."}, "author": {"ar": "جبران خليل جبران — النبي", "en": "Kahlil Gibran — The Prophet"}}, {"quote": {"ar": "ابنِ من خيالك عريشًا في البرية قبل أن تبني بيتًا داخل أسوار المدينة.", "en": "Build of your imaginings a bower in the wilderness ere you build a house within the city walls."}, "author": {"ar": "جبران خليل جبران — النبي", "en": "Kahlil Gibran — The Prophet"}}, {"quote": {"ar": "البيت حيث يكون القلب.", "en": "Home is where the heart is."}, "author": {"ar": "يُنسب إلى بلينيوس الأكبر", "en": "Attributed to Pliny the Elder"}}, {"quote": {"ar": "أصحاب الأراضي يزدادون ثراءً وهم نائمون.", "en": "Landlords grow rich in their sleep."}, "author": {"ar": "جون ستيوارت مل", "en": "John Stuart Mill"}}, {"quote": {"ar": "أفضل استثمار على الأرض هو الأرض.", "en": "The best investment on earth is earth."}, "author": {"ar": "لويس غليكمان", "en": "Louis Glickman"}}, {"quote": {"ar": "اشترِ أرضًا؛ فهم لم يعودوا يصنعون المزيد منها.", "en": "Buy land, they''re not making it anymore."}, "author": {"ar": "يُنسب إلى مارك توين", "en": "Attributed to Mark Twain"}}, {"quote": {"ar": "لا تنتظر لتشتري عقارًا؛ اشترِ عقارًا وانتظر.", "en": "Don''t wait to buy real estate. Buy real estate and wait."}, "author": {"ar": "يُنسب إلى ويل روجرز", "en": "Attributed to Will Rogers"}}, {"quote": {"ar": "الجار قبل الدار.", "en": "Choose the neighbour before the house."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "اختر الجار قبل الدار، والرفيق قبل الطريق.", "en": "Choose the neighbour before the house, and the companion before the road."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "على قدّ لحافك مدّ رجليك.", "en": "Stretch your legs only as far as your quilt reaches."}, "author": {"ar": "مثل مصري", "en": "Egyptian proverb"}}, {"quote": {"ar": "القرش الأبيض ينفع في اليوم الأسود.", "en": "The white piaster helps on the black day."}, "author": {"ar": "مثل مصري", "en": "Egyptian proverb"}}, {"quote": {"ar": "اسأل مجرّب ولا تسأل حكيم.", "en": "Ask the experienced rather than the wise."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "ما خاب من استشار.", "en": "Whoever seeks counsel is never disappointed."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "في التأني السلامة، وفي العجلة الندامة.", "en": "In patience lies safety, and in haste lies regret."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "خير الأمور أوسطها.", "en": "The best of matters is the middle way."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "من جدّ وجد، ومن زرع حصد.", "en": "Who strives finds, and who sows reaps."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "الصبر مفتاح الفرج.", "en": "Patience is the key to relief."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "ليس كل ما يلمع ذهبًا.", "en": "Not all that glitters is gold."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "لكل مقام مقال.", "en": "Every occasion has its fitting words."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "الوقت كالسيف، إن لم تقطعه قطعك.", "en": "Time is like a sword: if you do not cut it, it cuts you."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "ربّ ضارّة نافعة.", "en": "Many a harm turns out to be a benefit."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "العلم في الصغر كالنقش على الحجر.", "en": "Learning in youth is like carving in stone."}, "author": {"ar": "مثل عربي", "en": "Arabic proverb"}}, {"quote": {"ar": "اللي بنى مصر كان في الأصل حلواني.", "en": "The one who built Egypt was originally a confectioner."}, "author": {"ar": "مثل مصري", "en": "Egyptian proverb"}}, {"quote": {"ar": "قيمة كل امرئ ما يُحسنه.", "en": "Each person''s worth lies in what they do well."}, "author": {"ar": "يُنسب إلى علي بن أبي طالب", "en": "Attributed to Ali ibn Abi Talib"}}, {"quote": {"ar": "الظلم مؤذن بخراب العمران.", "en": "Injustice heralds the ruin of civilisation."}, "author": {"ar": "ابن خلدون — المقدمة", "en": "Ibn Khaldun — Al-Muqaddimah"}}, {"quote": {"ar": "الإنسان مدنيّ بالطبع.", "en": "Man is social by nature."}, "author": {"ar": "ابن خلدون — المقدمة", "en": "Ibn Khaldun — Al-Muqaddimah"}}, {"quote": {"ar": "على قدر أهل العزم تأتي العزائم، وتأتي على قدر الكرام المكارم.", "en": "Resolve comes in the measure of the resolute, and noble deeds in the measure of the noble."}, "author": {"ar": "المتنبي", "en": "Al-Mutanabbi"}}, {"quote": {"ar": "وما نيل المطالب بالتمنّي، ولكن تؤخذ الدنيا غِلابا.", "en": "Goals are not won by wishing; the world is taken by striving."}, "author": {"ar": "أحمد شوقي", "en": "Ahmed Shawqi"}}, {"quote": {"ar": "وإنما الأمم الأخلاق ما بقيت، فإن همُ ذهبت أخلاقهم ذهبوا.", "en": "Nations endure as long as their morals endure; when their morals go, they go."}, "author": {"ar": "أحمد شوقي", "en": "Ahmed Shawqi"}}, {"quote": {"ar": "إذا كنتَ في كلّ الأمور معاتبًا صديقَك، لم تلقَ الذي لا تعاتبه.", "en": "If you reproach your friend over everything, you will never find one you need not reproach."}, "author": {"ar": "بشار بن برد", "en": "Bashar ibn Burd"}}]'::jsonb) WHERE key = 'main_content';
